import{_ as a,a0 as r,w as l,s as h,ao as i,I as p,x as e,a1 as o,A as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"如何在 Ubuntu 15.04/CentOS 7 中安装 Lighttpd Web 服务器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 15.04/CentOS 7 中安装 Lighttpd Web 服务器 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 15.04/CentOS 7 中安装 Lighttpd Web 服务器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 15.04/CentOS 7 中安装 Lighttpd Web 服务器 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160219 How to Setup Lighttpd Web server on Ubuntu 15.04 or CentOS 7","title":"如何在 Ubuntu 15.04/CentOS 7 中安装 Lighttpd Web 服务器","tag":"201607","desc":""},"relativePath":"201607/20160219 How to Setup Lighttpd Web server on Ubuntu 15.04 or CentOS 7.md","filePath":"[post].md"}'),s={name:"201607/20160219 How to Setup Lighttpd Web server on Ubuntu 15.04 or CentOS 7.md"};function g(u,t,c,b,m,f){const n=r("Link");return l(),h("div",null,[t[19]||(t[19]=i(`<h1 id="如何在-ubuntu-15-04-centos-7-中安装-lighttpd-web-服务器" tabindex="-1">如何在 Ubuntu 15.04/CentOS 7 中安装 Lighttpd Web 服务器 <a class="header-anchor" href="#如何在-ubuntu-15-04-centos-7-中安装-lighttpd-web-服务器" aria-label="Permalink to “如何在 Ubuntu 15.04/CentOS 7 中安装 Lighttpd Web 服务器”">​</a></h1><p>Lighttpd 是一款开源 Web 服务器软件。Lighttpd 安全快速，符合行业标准，适配性强并且针对高配置环境进行了优化。相对于其它的 Web 服务器而言，Lighttpd 占用内存更少；因其对 CPU 占用小和对处理速度的优化而在效率和速度方面从众多 Web 服务器中脱颖而出。而 Lighttpd 诸如 FastCGI、CGI、认证、输出压缩、URL 重写等高级功能更是那些面临性能压力的服务器的福音。</p><p>以下便是我们在运行 Ubuntu 15.04 或 CentOS 7 Linux 发行版的机器上安装 Lighttpd Web 服务器的简要流程。</p><h3 id="安装lighttpd" tabindex="-1">安装Lighttpd <a class="header-anchor" href="#安装lighttpd" aria-label="Permalink to “安装Lighttpd”">​</a></h3><h4 id="使用包管理器安装" tabindex="-1">使用包管理器安装 <a class="header-anchor" href="#使用包管理器安装" aria-label="Permalink to “使用包管理器安装”">​</a></h4><p>这里我们通过使用包管理器这种最简单的方法来安装 Lighttpd。只需以 sudo 模式在终端或控制台中输入下面的指令即可。</p><p><strong>CentOS 7</strong></p><p>由于 CentOS 7.0 官方仓库中并没有提供 Lighttpd，所以我们需要在系统中安装额外的软件源 epel 仓库。使用下面的 yum 指令来安装 epel。</p><pre><code># yum install epel-release
</code></pre><p>然后，我们需要更新系统及为 Lighttpd 的安装做前置准备。</p><pre><code># yum update
# yum install lighttpd
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2016/02/install-lighttpd-centos.png" alt="Install Lighttpd Centos"></p><p><strong>Ubuntu 15.04</strong></p><p>Ubuntu 15.04 官方仓库中包含了 Lighttpd，所以只需更新本地仓库索引并使用 apt-get 指令即可安装 Lighttpd。</p><pre><code># apt-get update
# apt-get install lighttpd
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2016/02/install-lighttpd-ubuntu.png" alt="Install lighttpd ubuntu"></p><h4 id="从源代码安装-lighttpd" tabindex="-1">从源代码安装 Lighttpd <a class="header-anchor" href="#从源代码安装-lighttpd" aria-label="Permalink to “从源代码安装 Lighttpd”">​</a></h4><p>如果想从 Lighttpd 源码安装最新版本（例如 1.4.39），我们需要在本地编译源码并进行安装。首先我们要安装编译源码所需的依赖包。</p><pre><code># cd /tmp/
# wget http://download.lighttpd.net/lighttpd/releases-1.4.x/lighttpd-1.4.39.tar.gz
</code></pre><p>下载完成后，执行下面的指令解压缩。</p><pre><code># tar -zxvf lighttpd-1.4.39.tar.gz
</code></pre><p>然后使用下面的指令进行编译。</p><pre><code># cd lighttpd-1.4.39
# ./configure
# make
</code></pre><p><strong>注：</strong>在这份教程中，我们安装的是默认配置的 Lighttpd。其他拓展功能，如对 SSL 的支持，mod_rewrite，mod_redirect 等，需自行配置。</p><p>当编译完成后，我们就可以把它安装到系统中了。</p><pre><code># make install
</code></pre><h3 id="设置-lighttpd" tabindex="-1">设置 Lighttpd <a class="header-anchor" href="#设置-lighttpd" aria-label="Permalink to “设置 Lighttpd”">​</a></h3><p>如果有更高的需求，我们可以通过修改默认设置文件，如<code>/etc/lighttpd/lighttpd.conf</code>，来对 Lighttpd 进行进一步设置。 而在这份教程中我们将使用默认设置，不对设置文件进行修改。如果你曾做过修改并想检查设置文件是否出错，可以执行下面的指令。</p><pre><code># lighttpd -t -f /etc/lighttpd/lighttpd.conf
</code></pre><h4 id="使用-centos-7" tabindex="-1">使用 CentOS 7 <a class="header-anchor" href="#使用-centos-7" aria-label="Permalink to “使用 CentOS 7”">​</a></h4><p>在 CentOS 7 中，我们需创建一个在 Lighttpd 默认配置文件中设置的 webroot 文件夹，例如<code>/src/www/htdocs</code>。</p><pre><code># mkdir -p /srv/www/htdocs/
</code></pre><p>而后将默认欢迎页面从<code>/var/www/lighttpd</code>复制至刚刚新建的目录中：</p><pre><code># cp -r /var/www/lighttpd/* /srv/www/htdocs/
</code></pre><h3 id="开启服务" tabindex="-1">开启服务 <a class="header-anchor" href="#开启服务" aria-label="Permalink to “开启服务”">​</a></h3><p>现在，通过执行 systemctl 指令来重启 Web 服务。</p><pre><code># systemctl start lighttpd
</code></pre><p>然后我们将它设置为伴随系统启动自动运行。</p><pre><code># systemctl enable lighttpd
</code></pre><h3 id="设置防火墙" tabindex="-1">设置防火墙 <a class="header-anchor" href="#设置防火墙" aria-label="Permalink to “设置防火墙”">​</a></h3><p>如要让我们运行在 Lighttpd 上的网页或网站能在 Internet 或同一个网络内被访问，我们需要在防火墙程序中设置打开 80 端口。由于 CentOS 7 和 Ubuntu15.04 都附带 Systemd 作为默认初始化系统，所以我们默认用的都是 firewalld。如果要打开 80 端口或 http 服务，我们只需执行下面的命令：</p><pre><code># firewall-cmd --permanent --add-service=http
success
# firewall-cmd --reload
success
</code></pre><h3 id="连接至-web-服务器" tabindex="-1">连接至 Web 服务器 <a class="header-anchor" href="#连接至-web-服务器" aria-label="Permalink to “连接至 Web 服务器”">​</a></h3>`,43)),p("p",null,[t[1]||(t[1]=e("在将 80 端口设置为默认端口后，我们就可以直接访问 Lighttpd 的默认欢迎页了。我们需要根据运行 Lighttpd 的设备来设置浏览器的 IP 地址和域名。在本教程中，我们令浏览器访问 ",-1)),o(n,{href:"http://lighttpd.linoxide.com/"},{default:d(()=>[...t[0]||(t[0]=[e("http://lighttpd.linoxide.com/",-1)])]),_:1}),t[2]||(t[2]=e(" ，同时将该子域名指向上述 IP 地址。如此一来，我们就可以在浏览器中看到如下的欢迎页面了。",-1))]),t[20]||(t[20]=i(`<p><img src="http://blog.linoxide.com/wp-content/uploads/2016/02/lighttpd-welcome-page.png" alt="Lighttpd Welcome Page"></p><p>此外，我们可以将网站的文件添加到 webroot 目录下，并删除 Lighttpd 的默认索引文件，使我们的静态网站可以在互联网上访问。</p><p>如果想在 Lighttpd Web 服务器中运行 PHP 应用，请参考下面的步骤：</p><h3 id="安装-php5-模块" tabindex="-1">安装 PHP5 模块 <a class="header-anchor" href="#安装-php5-模块" aria-label="Permalink to “安装 PHP5 模块”">​</a></h3><p>在 Lighttpd 成功安装后，我们需要安装 PHP 及相关模块，以在 Lighttpd 中运行 PHP5 脚本。</p><h4 id="使用-ubuntu-15-04" tabindex="-1">使用 Ubuntu 15.04 <a class="header-anchor" href="#使用-ubuntu-15-04" aria-label="Permalink to “使用 Ubuntu 15.04”">​</a></h4><pre><code># apt-get install php5 php5-cgi php5-fpm php5-mysql php5-curl php5-gd php5-intl php5-imagick php5-mcrypt php5-memcache php-pear
</code></pre><h4 id="使用-centos-7-1" tabindex="-1">使用 CentOS 7 <a class="header-anchor" href="#使用-centos-7-1" aria-label="Permalink to “使用 CentOS 7”">​</a></h4><pre><code># yum install php php-cgi php-fpm php-mysql php-curl php-gd php-intl php-pecl-imagick php-mcrypt php-memcache php-pear lighttpd-fastcgi
</code></pre><h3 id="设置-lighttpd-的-php-服务" tabindex="-1">设置 Lighttpd 的 PHP 服务 <a class="header-anchor" href="#设置-lighttpd-的-php-服务" aria-label="Permalink to “设置 Lighttpd 的 PHP 服务”">​</a></h3><p>如要让 PHP 与 Lighttpd 协同工作，我们只要根据所使用的发行版执行如下对应的指令即可。</p><h4 id="使用-centos-7-2" tabindex="-1">使用 CentOS 7 <a class="header-anchor" href="#使用-centos-7-2" aria-label="Permalink to “使用 CentOS 7”">​</a></h4><p>首先要做的便是使用文件编辑器编辑 php 设置文件（例如<code>/etc/php.ini</code>）并取消掉对<strong>cgi.fix_pathinfo=1</strong>这一行的注释。</p><pre><code># nano /etc/php.ini
</code></pre><p>完成上面的步骤之后，我们需要把 PHP-FPM 进程的所有权从 Apache 转移至 Lighttpd。要完成这些，首先用文件编辑器打开<code>/etc/php-fpm.d/www.conf</code>文件。</p><pre><code># nano /etc/php-fpm.d/www.conf
</code></pre><p>然后在文件中增加下面的语句：</p><pre><code>user = lighttpd
group = lighttpd
</code></pre><p>做完这些，我们保存并退出文本编辑器。然后从<code>/etc/lighttpd/modules.conf</code>设置文件中添加 FastCGI 模块。</p><pre><code># nano /etc/lighttpd/modules.conf
</code></pre><p>然后，去掉下面语句前面的<code>#</code>来取消对它的注释。</p><pre><code>include &quot;conf.d/fastcgi.conf&quot;
</code></pre><p>最后我们还需在文本编辑器设置 FastCGI 的设置文件。</p><pre><code># nano /etc/lighttpd/conf.d/fastcgi.conf
</code></pre><p>在文件尾部添加以下代码：</p><pre><code>fastcgi.server += ( &quot;.php&quot; =&gt;
((
&quot;host&quot; =&gt; &quot;127.0.0.1&quot;,
&quot;port&quot; =&gt; &quot;9000&quot;,
&quot;broken-scriptfilename&quot; =&gt; &quot;enable&quot;
))
)
</code></pre><p>在编辑完成后保存并退出文本编辑器即可。</p><h4 id="使用-ubuntu-15-04-1" tabindex="-1">使用 Ubuntu 15.04 <a class="header-anchor" href="#使用-ubuntu-15-04-1" aria-label="Permalink to “使用 Ubuntu 15.04”">​</a></h4><p>如需启用 Lighttpd 的 FastCGI，只需执行下列代码：</p><pre><code># lighttpd-enable-mod fastcgi

Enabling fastcgi: ok
Run /etc/init.d/lighttpd force-reload to enable changes

# lighttpd-enable-mod fastcgi-php

Enabling fastcgi-php: ok
Run \`/etc/init.d/lighttpd\` force-reload to enable changes
</code></pre><p>然后，执行下列命令来重启 Lighttpd。</p><pre><code># systemctl force-reload lighttpd
</code></pre><h3 id="检测-php-工作状态" tabindex="-1">检测 PHP 工作状态 <a class="header-anchor" href="#检测-php-工作状态" aria-label="Permalink to “检测 PHP 工作状态”">​</a></h3><p>如需检测 PHP 是否按预期工作，我们需在 Lighttpd 的 webroot 目录下新建一个 php 文件。本教程中，在 Ubuntu 下 /var/www/html 目录，CentOS 下 /src/www/htdocs 目录下使用文本编辑器创建并打开 info.php。</p><p><strong>使用 CentOS 7</strong></p><pre><code># nano  /var/www/info.php
</code></pre><p><strong>使用 Ubuntu 15.04</strong></p><pre><code># nano /srv/www/htdocs/info.php
</code></pre><p>然后只需将下面的语句添加到文件里即可。</p><pre><code>&lt;?php phpinfo(); ?&gt;
</code></pre><p>在编辑完成后保存并推出文本编辑器即可。</p>`,41)),p("p",null,[t[4]||(t[4]=e("现在，我们需根据路径 ",-1)),o(n,{href:"http://lighttpd.linoxide.com/info.php"},{default:d(()=>[...t[3]||(t[3]=[e("http://lighttpd.linoxide.com/info.php",-1)])]),_:1}),t[5]||(t[5]=e(" 下的 info.php 文件的 IP 地址或域名，来让我们的网页浏览器指向系统上运行的 Lighttpd。如果一切都按照以上说明进行，我们将看到如下图所示的 PHP 页面信息。",-1))]),t[21]||(t[21]=p("p",null,[p("img",{src:"http://blog.linoxide.com/wp-content/uploads/2016/02/phpinfo-lighttpd.png",alt:"phpinfo lighttpd"})],-1)),t[22]||(t[22]=p("h3",{id:"总结",tabindex:"-1"},[e("总结 "),p("a",{class:"header-anchor",href:"#总结","aria-label":"Permalink to “总结”"},"​")],-1)),t[23]||(t[23]=p("p",null,"至此，我们已经在 CentOS 7 和 Ubuntu 15.04 Linux 发行版上成功安装了轻巧快捷并且安全的 Lighttpd Web 服务器。现在，我们已经可以上传网站文件到网站根目录、配置虚拟主机、启用 SSL、连接数据库，在我们的 Lighttpd Web 服务器上运行 Web 应用等功能了。 如果你有任何疑问，建议或反馈请在下面的评论区中写下来以让我们更好的改良 Lighttpd。谢谢！",-1)),t[24]||(t[24]=p("hr",null,null,-1)),p("p",null,[t[7]||(t[7]=e("via: ",-1)),o(n,{href:"http://linoxide.com/linux-how-to/setup-lighttpd-web-server-ubuntu-15-04-centos-7/"},{default:d(()=>[...t[6]||(t[6]=[e("http://linoxide.com/linux-how-to/setup-lighttpd-web-server-ubuntu-15-04-centos-7/",-1)])]),_:1})]),p("p",null,[t[11]||(t[11]=e("作者：",-1)),o(n,{href:"http://linoxide.com/author/arunp/"},{default:d(()=>[...t[8]||(t[8]=[e("Arun Pyasi",-1)])]),_:1}),t[12]||(t[12]=e(" 译者：",-1)),o(n,{href:"https://github.com/HaohongWANG"},{default:d(()=>[...t[9]||(t[9]=[e("HaohongWANG",-1)])]),_:1}),t[13]||(t[13]=e(" 校对：",-1)),o(n,{href:"https://github.com/wxy"},{default:d(()=>[...t[10]||(t[10]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[16]||(t[16]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...t[14]||(t[14]=[e("LCTT",-1)])]),_:1}),t[17]||(t[17]=e(" 原创编译，",-1)),o(n,{href:"https://linux.cn/"},{default:d(()=>[...t[15]||(t[15]=[e("Linux中国",-1)])]),_:1}),t[18]||(t[18]=e(" 荣誉推出",-1))])])}const C=a(s,[["render",g]]);export{P as __pageData,C as default};
